//@category Getaway
import ghidra.app.script.GhidraScript; import ghidra.app.decompiler.*; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*; import ghidra.program.model.address.*; import java.io.*; import java.util.*;
public class Refs extends GhidraScript { Address A(long o){ return currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(o); }
 public void run() throws Exception { String[] a=getScriptArgs(); FunctionManager FM=currentProgram.getFunctionManager(); ReferenceManager RM=currentProgram.getReferenceManager(); DecompInterface ifc=new DecompInterface(); ifc.openProgram(currentProgram); Set<Function> todo=new LinkedHashSet<>();
  try(PrintWriter pw=new PrintWriter(a[0]+"/refs.txt")){ for(int i=1;i<a.length;i++){ long t=Long.parseLong(a[i],16); pw.println("== refs to "+a[i]); for(long x=t;x<t+(a[i].length()>6?0:0x40);x+=4) for(Reference r: RM.getReferencesTo(A(x))){ Function f=FM.getFunctionContaining(r.getFromAddress()); pw.printf("  %08x <- %s @%s %s\n",x,f!=null?f.getName():"?",r.getFromAddress(),r.getReferenceType()); if(f!=null&&f.getBody().getNumAddresses()<6000) todo.add(f);} } }
  for(Function f: todo){ DecompileResults r=ifc.decompileFunction(f,90,monitor); try(PrintWriter pw=new PrintWriter(a[0]+"/decomp/"+f.getName()+".c")){ pw.print(r.getDecompiledFunction()!=null?r.getDecompiledFunction().getC():"// fail "+r.getErrorMessage()); } } println("done "+todo.size()); } }
